import json,re,sys
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[3];sys.path.insert(0,str(R/'scripts'));from migrate_learner_history import connection
D=json.loads((H/'current.json').read_text());P=json.loads((H/'proposed.json').read_text());db=connection();basis=db.basis();links=db.query('[:find ?kp ?q :in $ ?t :where [?t :topic/knowledge-points ?kp] (or [?kp :knowledge-point/questions ?q] [?kp :knowledge-point/canonical-example ?q])]',[D['topic']],H,'final-question-links',basis);ids=sorted({q for kp,q in links});assert ids==sorted(q[':db/id']for q in P['questions']),('Pool membership changed; audit new questions before completion',ids)
pattern='[* {:question/answer-fields [* {:answer-field/type [:db/id :db/ident]} {:answer-field/correct [* {:answer/type [:db/id :db/ident]}]} {:answer-field/choices [* {:answer/type [:db/id :db/ident]}]}]}]';actual=[r[0]for r in db.query('[:find (pull ?q '+pattern+') :in $ [?q ...] :where [?q :question/id ?id]]',[ids],H,'final-questions',basis)]
def signature(q):return {'id':str(q[':question/id']),'problem':q[':question/problem'],'solution':q.get(':question/worked-solution'),'fields':sorted([(f[':db/id'],f[':answer-field/key'],f[':answer-field/type'][':db/id'],f.get(':answer-field/correct',{}).get(':db/id'),sorted((a[':db/id'],a[':answer/type'][':db/id'],a[':answer/value'])for a in f[':answer-field/choices']))for f in q.get(':question/answer-fields',[])])}
expected={q[':db/id']:signature(q)for q in P['questions']};assert {q[':db/id']:signature(q)for q in actual}==expected
want={s[':step/content'][':db/id']:s[':step/content'][':tutorial/content']for a in P['structure']for s in a[':activity/steps']if':tutorial/content'in s[':step/content']};rows=db.query('[:find ?e ?v :in $ [?e ...] :where [?e :tutorial/content ?v]]',[list(want)],H,'final-tutorials',basis);assert dict(rows)==want
refs=db.query('[:find ?kp ?g ?script :in $ [?kp ...] :where [?kp :knowledge-point/question-generator ?g] [?g :question-generator/script ?script]]',[[k[':db/id']for k in D['knowledge_points']]],H,'final-generators',basis);packages=json.loads((H/'generator-publications.json').read_text());assert {kp:s for kp,g,s in refs}=={d['kp']:d['new_reference']for d in packages}
assert all(':answer-field/correct'in f for q in actual for f in q.get(':question/answer-fields',[]));assert not any(re.search(r'(?m)^\|',q[':question/problem'])for q in actual if any(f[':answer-field/type'][':db/ident']==':answer-field.type/blank'for f in q.get(':question/answer-fields',[])))
out={'basis_t':basis,'questions':len(actual),'tutorials':len(want),'canonical_examples':2,'practice_questions':len(actual)-2,'matrix_entry_questions':sum(any(f[':answer-field/type'][':db/ident']==':answer-field.type/blank'for f in q.get(':question/answer-fields',[]))for q in actual),'all_reviewed_content_matches_database':True,'all_keys_complete':True,'no_flattened_matrix_answer_tables':True,'pool_membership_preserved':True,'new_generator_registrations_verified':refs,'passed':True};(H/'final-verification.json').write_text(json.dumps(out,default=str,indent=2)+'\n');print(json.dumps(out,default=str,indent=2))
